///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {

};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getProvider
 * @description get Provider 처리
 * @returns {void}
 * @hidden N
 */
scwin.getProvider = function() {
    const url = frame.srcUrl;
    const arr = url.split("?")[1];
    return (arr.length >= 1 ? arr : undefined);
};

/**
 * @method
 * @name closeWin
 * @description 화면닫기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.closeWin = async function() {
    await $c.win.closePopup();
};
